package com.jadhavr.erp.email.template;import org.springframework.stereotype.Component;import org.thymeleaf.TemplateEngine;import org.thymeleaf.context.Context;import java.util.Map;@Component public class EmailTemplateRenderer{private final TemplateEngine engine;public EmailTemplateRenderer(TemplateEngine e){engine=e;}public String render(String name,Map<String,String>data,String subject){Context c=new Context();c.setVariables(Map.copyOf(data));c.setVariable("subject",subject);c.setVariable("year",java.time.Year.now().getValue());return engine.process("email/"+name,c);}}
